#include "gtest/gtest.h"
#include "population_dynamics/maturity/functors/empirical.hpp"

namespace {

// EmpiricalMaturity_evaluate
// IO correctness
// Test that n_ages values are returned by age and reused in every year.
TEST(EmpiricalMaturity_evaluate, HandlesCorrectInput) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(3);
  maturity.maturity_at_age[0] = 0.1;
  maturity.maturity_at_age[1] = 0.5;
  maturity.maturity_at_age[2] = 0.9;
  maturity.min_age = 2;
  maturity.n_ages = 3;
  double expected[3] = {0.1, 0.5, 0.9};

  for (size_t age = 2; age < 5; ++age) {
    EXPECT_EQ(maturity.evaluate(age), expected[age - 2]);
    for (size_t pos = 0; pos < 3; ++pos) {
      EXPECT_EQ(maturity.evaluate(age, pos), expected[age - 2]);
    }
  }
}

// IO correctness
// Test that n_ages values per year are used by year, with age changing
// fastest within each year.
TEST(EmpiricalMaturity_evaluate, HandlesTimeVaryingValues) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(4);
  // year 1: ages 1 and 2; year 2: ages 1 and 2
  maturity.maturity_at_age[0] = 0.2;
  maturity.maturity_at_age[1] = 0.6;
  maturity.maturity_at_age[2] = 0.3;
  maturity.maturity_at_age[3] = 0.8;
  maturity.min_age = 1;
  maturity.n_ages = 2;

  EXPECT_EQ(maturity.evaluate(1.0, 0), 0.2);
  EXPECT_EQ(maturity.evaluate(2.0, 0), 0.6);
  EXPECT_EQ(maturity.evaluate(1.0, 1), 0.3);
  EXPECT_EQ(maturity.evaluate(2.0, 1), 0.8);
}

// Edge handling
// Test that 1 value is used for every age and year.
TEST(EmpiricalMaturity_evaluate, HandlesSingleValue) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(1);
  maturity.maturity_at_age[0] = 1.0;
  maturity.min_age = 1;
  maturity.n_ages = 3;

  for (size_t pos = 0; pos < 3; ++pos) {
    for (size_t age = 1; age < 4; ++age) {
      EXPECT_EQ(maturity.evaluate(age, pos), 1.0);
    }
  }
}

// Error handling
// Test that a length that is not 1 or a multiple of n_ages throws instead of
// reusing values for the wrong ages.
TEST(EmpiricalMaturity_evaluate, ThrowsForWrongLength) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(3);
  maturity.min_age = 1;
  maturity.n_ages = 2;

  EXPECT_THROW(maturity.evaluate(1.0, 0), std::invalid_argument);
}

// Error handling
// Test that ages outside the modeled ages throw instead of reading another
// age's value.
TEST(EmpiricalMaturity_evaluate, ThrowsForAgeOutsideModel) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(2);
  maturity.min_age = 1;
  maturity.n_ages = 2;

  EXPECT_THROW(maturity.evaluate(0.0, 0), std::invalid_argument);
  EXPECT_THROW(maturity.evaluate(3.0, 0), std::invalid_argument);
}

// Error handling
// Test that a year beyond the time-varying values throws.
TEST(EmpiricalMaturity_evaluate, ThrowsForYearBeyondValues) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(4);
  maturity.min_age = 1;
  maturity.n_ages = 2;

  EXPECT_THROW(maturity.evaluate(1.0, 2), std::invalid_argument);
}

// Error handling
// Test that evaluate() without a year throws for time-varying values rather
// than silently using the first year.
TEST(EmpiricalMaturity_evaluate, ThrowsWithoutYearWhenTimeVarying) {
  fims_popdy::EmpiricalMaturity<double> maturity;
  maturity.maturity_at_age.resize(4);
  maturity.min_age = 1;
  maturity.n_ages = 2;

  EXPECT_THROW(maturity.evaluate(1.0), std::invalid_argument);
}

}  // namespace
